cat > /tmp/repro_extended.py <<'EOF'
import pandas as pd
import numpy as np
from qualitystats.counters import quality_counts

test_cases = [
    {
        "name": "Example from issue",
        "reading": [0, 1, np.nan, 2],
        "baseline": [0, 2, 1, 4],
        "expected": {"missing": 1, "undefined_ratio": 1}
    },
    {
        "name": "All missing",
        "reading": [np.nan, np.nan],
        "baseline": [np.nan, np.nan],
        "expected": {"missing": 2, "undefined_ratio": 0}
    },
    {
        "name": "All undefined",
        "reading": [0, 0],
        "baseline": [0, 0],
        "expected": {"missing": 0, "undefined_ratio": 2}
    },
    {
        "name": "Mixed missing and undefined",
        "reading": [np.nan, 0, np.nan, 0],
        "baseline": [0, np.nan, np.nan, 0],
        "expected": {"missing": 3, "undefined_ratio": 1}
    },
    {
        "name": "No missing or undefined",
        "reading": [1, 2],
        "baseline": [1, 2],
        "expected": {"missing": 0, "undefined_ratio": 0}
    },
    {
        "name": "Inf case (reading != 0, baseline == 0)",
        "reading": [1],
        "baseline": [0],
        "expected": {"missing": 0, "undefined_ratio": 0}
    }
]

for case in test_cases:
    df = pd.DataFrame({
        "reading": pd.Series(case["reading"], dtype="Float64"),
        "baseline": pd.Series(case["baseline"], dtype="Float64")
    })
    result = quality_counts(df)
    print(f"Case: {case['name']}")
    print(f"Result: {result}, Expected: {case['expected']}")
    assert result == case["expected"]
    print("PASS")
    print("-" * 20)
EOF
python3 /tmp/repro_extended.py
